import { PlayerCard } from './types.js';
import { generatePlayerSvgUri } from './avatar-fallback.js';

/**
 * Açılış Fiyatı Formülü (Ekonomi v1):
 * P0 = max(2, round(2 + 0.0085 * (OVR - 50)^2))
 */
export function calculateBasePrice(ovr: number): number {
  return Math.max(2, Math.round(2 + 0.0085 * Math.pow(ovr - 50, 2)));
}

